// Generated by Cypress Author on 2026-10-02.
import { mountWorkspace, mockRefresh, task } from "../../support/tasks";

describe("Edit tasks", () => {
  beforeEach(() => {
    mountWorkspace([task()]);
    cy.get('[aria-label="Edit Buy groceries"]').click();
    cy.get("#task-title").should("have.value", "Buy groceries");
    cy.get("#task-description").should("have.value", "Milk and bread");
  });

  it("edits a task → saves both fields and refreshes the existing row", () => {
    const updated = task({ title: "Order groceries", description: "Deliver tomorrow" });
    cy.intercept("PUT", "/api/tasks/42", { statusCode: 200, body: updated }).as("updateTask");
    mockRefresh([updated]);
    cy.get("#task-title").clear().type(updated.title);
    cy.get("#task-description").clear().type(updated.description);
    cy.contains("dialog button", "Save changes").click();
    cy.wait("@updateTask").its("request.body").should("deep.equal", {
      title: updated.title, description: updated.description,
    });
    cy.wait("@refreshTasks");
    cy.get("dialog").should("not.exist");
    cy.get('[role="status"]').should("have.text", "Task updated.");
    cy.get('section[aria-label="Task list"] li').should("have.length", 1)
      .and("contain.text", updated.title).and("contain.text", updated.description)
      .and("not.contain.text", "Buy groceries");
    cy.get("@updateTask.all").should("have.length", 1);
  });

  it("fails to save → keeps the original row and entered edits for retry", () => {
    cy.intercept("PUT", "/api/tasks/42", {
      statusCode: 500, body: { message: "Unable to update task." },
    }).as("updateTask");
    cy.get("#task-title").clear().type("Order groceries");
    cy.contains("dialog button", "Save changes").click();
    cy.wait("@updateTask");
    cy.get('dialog [role="alert"]').should("have.text", "Unable to update task.");
    cy.get("#task-title").should("have.value", "Order groceries").and("not.be.disabled");
    cy.contains("dialog button", "Save changes").should("be.enabled");
    cy.get('section[aria-label="Task list"] li').should("contain.text", "Buy groceries");
    cy.get('[role="status"]').should("not.exist");
  });

  it("cancels edits → keeps the task unchanged without saving", () => {
    cy.intercept("PUT", "/api/tasks/42", { statusCode: 200, body: task() }).as("updateTask");
    cy.get("#task-title").clear().type("Discard this edit");
    cy.contains("dialog button", "Cancel").click();
    cy.get("dialog").should("not.exist");
    cy.get('section[aria-label="Task list"] li').should("contain.text", "Buy groceries")
      .and("not.contain.text", "Discard this edit");
    cy.get('[aria-label="Edit Buy groceries"]').should("be.focused");
    cy.get("@updateTask.all").should("have.length", 0);
  });
});
